#include <vector>
#include <cstddef>
#include <omp.h>

size_t findFirstEven(std::vector<int> const& x) {
    size_t first = x.size();

    #pragma omp parallel
    {
        size_t local_first = x.size();

        #pragma omp for nowait
        for (size_t i = 0; i < x.size(); ++i) {
            if ((x[i] % 2) == 0 && i < local_first) {
                local_first = i;
            }
        }

        #pragma omp critical
        {
            if (local_first < first) {
                first = local_first;
            }
        }
    }

    return first;
}
